# Global registry of live sub-agent instances keyed by name.
AGENT_REGISTRY: dict[str, "Agent"] = {}

# Placeholder credential for loopback endpoints. The OpenAI-compatible SDK
# requires a non-empty key string, but local endpoints need no real
# credential; this value is never sent to a remote host.
_LOOPBACK_API_KEY = "local"


class ProviderCredentialsError(MythicProviderError, RuntimeError):
    """A remote endpoint needs a credential and none is configured.

    Raised before any network request, with a redacted remedy. Loopback
    endpoints never raise this: they may operate without auth.
    """


def _key_env_hint(base_url: str) -> str:
    """Name the environment variable that carries this endpoint's key."""
    if "deepseek" in base_url:
        return "DEEPSEEK_API_KEY"
    if "openrouter" in base_url:
        return "OPENROUTER_API_KEY"
    if "anthropic" in base_url:
        return "ANTHROPIC_API_KEY"
    return "OPENAI_API_KEY"


def _missing_key_remedy(base_url: str) -> str:
    """The one plain remedy for a door with no key (M-032).

    The wording is M-032's :func:`missing_key_message`: it asks
    once, kindly, naming the Kista reference to add and the
    environment variable — config files hold references, never
    secrets. Loopback endpoints need no key.
    """
    from ..core.key_custody import missing_key_message

    return missing_key_message(base_url)


def resolve_api_key(config: dict[str, Any], base_url: str) -> str | None:
    """Return the configured credential for an endpoint, if any.

    A stored Kista reference (M-032) resolves through Kista —
    its vault file, then the environment under the reference's
    own name; an unresolved reference returns None here (no
    other door's key, and not the door's hint variable either,
    is substituted for the key the reference names). A legacy
    plaintext stored key is itself. Otherwise the provider's
    environment variable answers. Returns None when nothing is
    configured; it is the caller's job to decide whether that
    is an error (remote) or fine (loopback).
    """
    from ..core.key_custody import is_reference, stored_key_for

    stored = config.get("api_keys", {}).get(base_url)
    if stored:
        resolved = stored_key_for(config, base_url)
        if resolved:
            return resolved
        if is_reference(stored):
            return None
    return os.environ.get(_key_env_hint(base_url))


def build_provider_client(config: dict[str, Any],
                          cancel: threading.Event | None = None) -> CancellableChatClient:
    """Construct the provider HTTP client honoring S07 admission rules.

    Loopback endpoints operate without auth (an inert placeholder satisfies
    the SDK) and never consult proxy environment. Remote endpoints without
    a configured credential fail here, before any network request, with a
    redacted remedy; invented dummy credentials are never substituted.
    """
    base_url = config.get("base_url", config_manager.DEFAULT_BASE_URL)
    settings = runtime_settings(config)
    cancel = cancel if cancel is not None else threading.Event()
    if is_loopback_url(base_url):
        api_key = resolve_api_key(config, base_url) or _LOOPBACK_API_KEY
        return CancellableChatClient(base_url, api_key, cancel,
                                     settings["request_timeout"],
                                     settings["cancellation_poll_interval"],
                                     trust_env=False)
    api_key = resolve_api_key(config, base_url)
    if not api_key:
        raise ProviderCredentialsError(_missing_key_remedy(base_url))
    return CancellableChatClient(base_url, api_key, cancel,
                                 settings["request_timeout"],
                                 settings["cancellation_poll_interval"])


def diagnose_provider(config: dict[str, Any]) -> dict[str, Any]:
    """Offline provider diagnostics: configuration only, no network.

    Reports configured values separately from anything verified live, and
    never includes key material.
    """
    base_url = config.get("base_url", config_manager.DEFAULT_BASE_URL)
    model = config.get("model", "") or ""
    loopback = is_loopback_url(base_url)
    settings = runtime_settings(config)
    return {
        "base_url": base_url,
        "base_url_valid": config_manager._valid_url(base_url),
        "loopback": loopback,
        "model": model,
        "model_configured": bool(model.strip()),
        "api_key_configured": bool(resolve_api_key(config, base_url)),
        "auth_required": not loopback,
        "streaming": bool(config.get("streaming", False)),
        "retry_budget": settings["max_retries"],
        "request_timeout": settings["request_timeout"],
    }


def _retry_delay(exc: Exception, attempt: int, settings: dict[str, Any]) -> float:
    """Capped backoff for one retry: server Retry-After wins when present.

    Thin wrapper over :func:`mythic_agent.core.retry_honesty.delay_for`
    (M-035); the semantics are unchanged.
    """
    from ..core.retry_honesty import delay_for

    return delay_for(exc, attempt, settings)


def _is_transient(exc: Exception) -> bool:
    """Classify provider errors: retry connection issues and 408/409/429/5xx.

    Auth (401/403), bad model (404), invalid requests (400/422), and
    capability failures fail promptly and are never retried. Thin
    wrapper over :func:`mythic_agent.core.retry_honesty.is_transient_error`
    (M-035); the classification is unchanged.
    """
    from ..core.retry_honesty import is_transient_error

    return is_transient_error(exc)


class _StreamAccumulator:
    """Accumulate SSE text/tool deltas into one normalized assistant message.

    Text fragments publish incrementally (each exactly once); indexed tool
    name/argument fragments reassemble per tool-call index. Tools execute
    only after the completed response validates: incomplete fragments or a
    malformed stream raise before anything becomes executable.
    """

    def __init__(self, agent_name: str):
        self._agent_name = agent_name
        self.reset()

    def reset(self) -> None:
        self._content: list[str] = []
        self._tool_calls: dict[int, dict[str, str]] = {}
        self._finish_reason: str | None = None
        self._usage: Any = None
        self._chunks_seen = 0

    @property
    def emitted(self) -> bool:
        """True once any chunk arrived: never retry after a partial response."""
        return self._chunks_seen > 0

    @property
    def text(self) -> str:
        return "".join(self._content)

    def __call__(self, chunk: Any) -> None:
        self._chunks_seen += 1
        for choice in chunk.choices or []:
            if choice.finish_reason:
                self._finish_reason = choice.finish_reason
            delta = choice.delta
            if delta is None:
                continue
            content = getattr(delta, "content", None)
            if content:
                self._content.append(content)
                publish_sync("agent_chat_chunk", agent_name=self._agent_name, text=content)
            for call in getattr(delta, "tool_calls", None) or []:
                index = getattr(call, "index", 0) or 0
                slot = self._tool_calls.setdefault(index, {"id": "", "name": "", "arguments": ""})
                if call.id:
                    slot["id"] = call.id
                function = call.function
                if function is not None:
                    if function.name:
                        slot["name"] = function.name
                    if function.arguments:
                        slot["arguments"] += function.arguments
        usage = getattr(chunk, "usage", None)
        if usage is not None:
            self._usage = usage

    def message(self) -> dict[str, Any]:
        """Return the normalized assistant message; raise on malformed streams."""
        if not self._chunks_seen:
            raise RuntimeError("Provider returned an empty stream")
        calls = []
        for index in sorted(self._tool_calls):
            slot = self._tool_calls[index]
            if not slot["id"] or not slot["name"]:
                raise RuntimeError(
                    "Provider stream ended with incomplete tool call fragments; "
                    "refusing to execute partial calls")
            calls.append({"id": slot["id"], "type": "function",
                          "function": {"name": slot["name"], "arguments": slot["arguments"]}})
        text = self.text
        if not text and not calls:
            raise RuntimeError("Provider returned an empty assistant response")
        message: dict[str, Any] = {"role": "assistant", "content": text or None}
        if calls:
            message["tool_calls"] = calls
        return message

def _role_route_for(config: dict, name: str):
    """The explicit role route for crew member *name*, or None (M-029).

    Shared by :class:`Agent` (route changes reaching live members)
    and :class:`AgentManager` (routes applied at spawn): the route
    is read from *config* — the manager has no config of its own, so
    it passes the freshly loaded one. An office with no explicit
    route, a name no office claims, and a malformed stored route
    all yield None here: spawn never breaks over routing, and the
    malformed route still surfaces at set/show time.
    """
    from ..core.role_routing import office_for_agent_name, resolve_route

    office = office_for_agent_name(name)
    if office is None:
        return None
    try:
        route = resolve_route(config, office)
    except ValueError:
        return None
    return route if route.source == "route" else None




class _CheckpointTimelineAdapter:
    """M-075 checkpoints speaking the M-077 seam (banking wiring).

    Coordinator wiring at M-077 banking: M-077's undo
    timeline reads its checkpoint strand through the
    ``checkpoint_timeline_source`` seam and M-075
    (Checkpoints v2) is banked, so the Agent carries
    this adapter by default (see the Agent property).
    Entries are M-075's own checkpoints (id as text,
    name as label; certainty is not claimed, so the
    seam's honest ``unknown`` default stands). Restore
    maps the seam id back to the checkpoint's name and
    drives the Agent's own M-075 restore road, whose
    dirty-tree judgement and gate refusals propagate
    unchanged; the outcome is returned in plain words,
    as the seam requires.
    """

    def __init__(self, agent: Any) -> None:
        self._agent = agent

    def list_checkpoint_entries(self) -> list[dict[str, Any]]:
        from ..core import checkpoints

        store = checkpoints.CheckpointStore(
            self._agent.project_root)
        return [{"id": str(cp.id), "name": cp.name}
                for cp in store.list_checkpoints()]

    def restore_checkpoint(self, checkpoint_id: str) -> str:
        from ..core import checkpoints

        store = checkpoints.CheckpointStore(
            self._agent.project_root)
        for cp in store.list_checkpoints():
            if str(cp.id) == str(checkpoint_id):
                record = self._agent.restore_checkpoint(cp.name)
                return (f"Restored checkpoint {cp.name!r}: "
                        f"{record['restored']} file(s) restored, "
                        f"{record['removed']} removed, "
                        f"{record['unchanged']} unchanged.")
        raise ValueError(
            f"no checkpoint with id {checkpoint_id!r} in "
            "this workspace; nothing was restored")

#: The /aesirdeepening slash grammar (M-245, agent layer).
AESIRDEEPENING_USAGE = (
    "Usage: /aesirdeepening | /aesirdeepening report | "
    "/aesirdeepening selections | /aesirdeepening selection "
    "<office> | /aesirdeepening ask <office> [needs...] "
    "[model:<name>] | /aesirdeepening index | "
    "/aesirdeepening verdict")


class AesirDeepeningRegistry:
    """Session registry for the Aesir deepening (M-245).

    The registry lives in the agent layer alone - it is
    session state, not a stored setting - and wraps the
    pure layer (``mythic_agent.core.aesir_deepening``): it
    holds one validated capability report and the
    per-office selections held one by one for the
    session, beside the shipped selection book. A report
    is validated whole by the pure layer before it is
    held - a report claiming more than Aesir's documented
    v1 ceiling refuses by name here too, and a refusal
    holds nothing new. A selection naming an office the
    crew does not hold, or a second selection for an
    office already held, refuses likewise. Holding opens
    no session, calls no model and probes no server:
    the registry holds tellings as data, alone.
    """

    def __init__(self) -> None:
        self._report: Any = None
        self._selections: dict[str, Any] = {}

    def register_report(self, report: Any):
        """Hold one capability report, validated whole."""
        from ..core.aesir_deepening import validate_report
        if not isinstance(report, dict):
            report = report.record()
        held = validate_report(report)
        self._report = held
        return held

    def report(self):
        """The held capability report, or None."""
        return self._report

    def register_selection(self, selection: Any):
        """Hold one office's selection, validated whole.

        A second selection for an office already held
        refuses, and a refusal holds nothing new.
        """
        from ..core.aesir_deepening import validate_selection
        if not isinstance(selection, dict):
            selection = selection.record()
        held = validate_selection(selection)
        if held.office in self._selections:
            raise ValueError(
                "a selection for office "
                f"{held.office!r} already stands held for "
                "the session")
        self._selections[held.office] = held
        return held

    def register_book(self, book: Any):
        """Hold a whole selection book's selections.

        The book is validated whole, and against the
        selections already held, before anything is
        held, so a refusal holds nothing new.
        """
        from ..core.aesir_deepening import (
            validate_selection_book)
        if not isinstance(book, dict):
            book = book.record()
        validated = validate_selection_book(book)
        for selection in validated.selections:
            if selection.office in self._selections:
                raise ValueError(
                    "a selection for office "
                    f"{selection.office!r} already stands "
                    "held for the session")
        for selection in validated.selections:
            self._selections[selection.office] = selection
        return validated

    def list_selections(self) -> list:
        """The selections held one by one, in hold order."""
        return list(self._selections.values())

    def list_items(self) -> list:
        """Everything held: the report, then selections."""
        items: list = []
        if self._report is not None:
            items.append(self._report)
        items.extend(self._selections.values())
        return items

    def get_selection(self, office: Any):
        """The held selection for one office, by name."""
        from ..core.validation import ValidationError
        try:
            return self._selections[office]
        except KeyError:
            raise ValidationError(
                "the session holds no selection for office "
                f"{office!r}") from None

    def book(self):
        """The held selections composed as a book."""
        from ..core.aesir_deepening import SelectionBook
        return SelectionBook(
            selections=tuple(self._selections.values()))


def parse_aesirdeepening_args(args: Any):
    """Parse /aesirdeepening arguments (M-245).

    Returns ``(stance, target, needs, model)``: the bare
    command and ``show`` stand as ``("show", None, (),
    None)``; ``report``, ``selections``, ``index`` and
    ``verdict`` name their own stance with no target;
    ``selection <office>`` names one office; ``ask
    <office> [needs...] [model:<name>]`` names the
    office, the needs in order, and an optional model
    token. Anything else raises ValueError carrying the
    usage line, exactly as the sibling parsers refuse.
    """
    text = (args or "").strip()
    if not text or text == "show":
        return ("show", None, (), None)
    parts = text.split()
    head, rest = parts[0], parts[1:]
    if head in ("report", "selections", "index", "verdict"):
        if rest:
            raise ValueError(AESIRDEEPENING_USAGE)
        return (head, None, (), None)
    if head == "selection":
        if len(rest) != 1:
            raise ValueError(AESIRDEEPENING_USAGE)
        return ("selection", rest[0], (), None)
    if head == "ask":
        if not rest:
            raise ValueError(AESIRDEEPENING_USAGE)
        needs: list = []
        model = None
        for token in rest[1:]:
            if token.startswith("model:"):
                if model is not None or not token[6:]:
                    raise ValueError(AESIRDEEPENING_USAGE)
                model = token[6:]
            else:
                needs.append(token)
        return ("ask", rest[0], tuple(needs), model)
    raise ValueError(AESIRDEEPENING_USAGE)


#: The /githostparity slash grammar (M-246, agent layer).
GITHOSTPARITY_USAGE = (
    "Usage: /githostparity | /githostparity hosts | "
    "/githostparity host <host> | /githostparity record "
    "<host> | /githostparity standing <host> | "
    "/githostparity index | /githostparity verdict")


class GitHostParityRegistry:
    """Session registry for the git host parity (M-246).

    The registry lives in the agent layer alone - it is
    session state, not a stored setting - and wraps the
    pure layer (``mythic_agent.core.git_host_parity``):
    it holds the shipped host registry (one entry per
    host, held as data like a provider registry) beside
    the parity records held one by one for the session,
    one record per host. A record is validated whole by
    the pure layer before it is held - a record naming
    an unknown craft, stage or claim refuses by name
    here too, and a refusal holds nothing new. A second
    record for a host already held refuses likewise.
    Holding calls no host API, clones nothing, pushes
    nothing and probes no network: the registry holds
    tellings as data, alone.
    """

    def __init__(self) -> None:
        from ..core.git_host_parity import load_host_registry
        self._hosts = load_host_registry()
        self._records: dict[str, Any] = {}

    def hosts(self):
        """The shipped host registry held by the session."""
        return self._hosts

    def register_record(self, record: Any):
        """Hold one host's parity record, validated whole.

        A second record for a host already held refuses,
        and a refusal holds nothing new.
        """
        from ..core.git_host_parity import (
            validate_parity_record)
        if not isinstance(record, dict):
            record = record.record()
        held = validate_parity_record(record)
        if held.host in self._records:
            raise ValueError(
                "a parity record for host "
                f"{held.host!r} already stands held for "
                "the session")
        self._records[held.host] = held
        return held

    def get_record(self, host: Any):
        """The held parity record for one host, by name."""
        from ..core.validation import ValidationError
        try:
            return self._records[host]
        except KeyError:
            raise ValidationError(
                "the session holds no parity record for "
                f"host {host!r}") from None

    def register_records(self, records: Any):
        """Hold a set of parity records, validated whole.

        Every record is validated, and checked against
        the records already held and within the set,
        before anything is held, so a refusal holds
        nothing new.
        """
        from ..core.git_host_parity import (
            validate_parity_record)
        validated = []
        seen: set = set()
        for record in records:
            if not isinstance(record, dict):
                record = record.record()
            held = validate_parity_record(record)
            if held.host in self._records or held.host in seen:
                raise ValueError(
                    "a parity record for host "
                    f"{held.host!r} already stands held "
                    "for the session")
            seen.add(held.host)
            validated.append(held)
        for held in validated:
            self._records[held.host] = held
        return validated

    def list_records(self) -> list:
        """The parity records held one by one, in hold order."""
        return list(self._records.values())

    def list_items(self) -> list:
        """Everything held: the parity records."""
        return list(self._records.values())

    def standings(self) -> list:
        """The held records' standings, derived at call time."""
        from ..core.git_host_parity import derive_standing
        return [derive_standing(record)
                for record in self._records.values()]

    def book(self):
        """The held pieces composed as a parity book.

        The book is plain data: the shipped host
        registry's entries beside the parity records
        held for the session, under the pure layer's
        schema word.
        """
        from ..core.git_host_parity import GIT_HOST_SCHEMA
        return {
            "schema": GIT_HOST_SCHEMA,
            "hosts": [entry.record()
                      for entry in self._hosts.hosts],
            "records": [record.record()
                        for record in self._records.values()],
        }


def parse_githostparity_args(args: Any):
    """Parse /githostparity arguments (M-246).

    Returns ``(stance, target, (), None)``: the bare
    command and ``show`` stand as ``("show", None, (),
    None)``; ``hosts``, ``index`` and ``verdict`` name
    their own stance with no target; ``host <host>``,
    ``record <host>`` and ``standing <host>`` name one
    host. Anything else raises ValueError carrying the
    usage line, exactly as the sibling parsers refuse.
    """
    text = (args or "").strip()
    if not text or text == "show":
        return ("show", None, (), None)
    parts = text.split()
    head, rest = parts[0], parts[1:]
    if head in ("hosts", "index", "verdict"):
        if rest:
            raise ValueError(GITHOSTPARITY_USAGE)
        return (head, None, (), None)
    if head in ("host", "record", "standing"):
        if len(rest) != 1:
            raise ValueError(GITHOSTPARITY_USAGE)
        return (head, rest[0], (), None)
    raise ValueError(GITHOSTPARITY_USAGE)


#: The /cibridges slash grammar (M-247, agent layer).
CIBRIDGES_USAGE = (
    "Usage: /cibridges | /cibridges providers | "
    "/cibridges provider <provider> | /cibridges record "
    "<provider> <workflow> | /cibridges standing "
    "<provider> <workflow> | /cibridges draft | "
    "/cibridges draft <provider> <workflow> | "
    "/cibridges index | /cibridges verdict")


def _ci_provider_dict(entry: Any) -> dict[str, Any]:
    """One CI provider registry entry, as plain data (M-247)."""
    return {"id": entry.id, "label": entry.label,
            "run_word": entry.run_word, "reason": entry.reason}


def _ci_record_dict(record: Any) -> dict[str, Any]:
    """One CI run record, as plain data (M-247)."""
    return {"provider": record.provider,
            "workflow": record.workflow, "ref": record.ref,
            "conclusion": record.conclusion,
            "stages": list(record.stages),
            "claims": list(record.claims)}


def _ci_standing_dict(standing: Any) -> dict[str, Any]:
    """One derived CI standing, as plain data (M-247)."""
    return {"held": standing.held, "stage": standing.stage,
            "gaps": list(standing.gaps)}


def _ci_draft_dict(draft: Any) -> dict[str, Any]:
    """One workflow draft, as plain data (M-247)."""
    return {"provider": draft.provider,
            "workflow": draft.workflow, "change": draft.change,
            "trigger": draft.trigger, "applied": draft.applied}


def _ci_draft_text(draft: Any) -> str:
    """One workflow draft told in plain words (M-247)."""
    return (f"{draft.provider}/{draft.workflow}: draft - "
            f"{draft.change} (trigger: {draft.trigger}; "
            "a draft is never applied here)")


def _ci_coerce_record(record: Any):
    """A CI run record from a record or a plain telling (M-247)."""
    from ..core.ci_bridges import CIRecord
    if isinstance(record, CIRecord):
        return record
    if isinstance(record, dict):
        return CIRecord(
            provider=record["provider"],
            workflow=record["workflow"], ref=record["ref"],
            conclusion=record["conclusion"],
            stages=tuple(record.get("stages", ())),
            claims=tuple(record.get("claims", ())))
    return CIRecord(
        provider=record.provider, workflow=record.workflow,
        ref=record.ref, conclusion=record.conclusion,
        stages=tuple(record.stages), claims=tuple(record.claims))


class CIBridgesRegistry:
    """Session registry for the CI bridges (M-247).

    The registry lives in the agent layer alone - it is
    session state, not a stored setting - and wraps the
    pure layer (``mythic_agent.core.ci_bridges``): it
    holds the shipped provider registry (one entry per
    provider, held as data) beside the CI run records
    held one by one for the session, one record per
    provider and workflow, and the workflow drafts
    proposed for the session, one draft per provider
    and workflow. A record is validated whole by the
    pure layer before it is held - a record naming an
    unknown provider, conclusion or evidence kind
    refuses by name here too, and a refusal holds
    nothing new. A second record for a provider and
    workflow already held refuses likewise. A draft is
    proposed only through the pure layer's draft road -
    manual dispatch by default, never applied. Holding
    calls no CI API, fetches no run, changes no
    workflow and dispatches nothing: the registry holds
    tellings as data, alone.
    """

    def __init__(self) -> None:
        from ..core.ci_bridges import default_registry
        self._providers = default_registry()
        self._records: dict[tuple, Any] = {}
        self._drafts: dict[tuple, Any] = {}

    def providers(self):
        """The shipped provider registry held by the session."""
        return self._providers

    def register_record(self, record: Any):
        """Hold one run's record, validated whole.

        A second record for a provider and workflow
        already held refuses, and a refusal holds
        nothing new.
        """
        held = _ci_coerce_record(record)
        held.validate(self._providers)
        key = (held.provider, held.workflow)
        if key in self._records:
            raise ValueError(
                "a ci record for provider "
                f"{held.provider!r} workflow "
                f"{held.workflow!r} already stands held "
                "for the session")
        self._records[key] = held
        return held

    def get_record(self, provider: Any, workflow: Any):
        """The held record for one provider and workflow."""
        from ..core.validation import ValidationError
        try:
            return self._records[(provider, workflow)]
        except KeyError:
            raise ValidationError(
                "the session holds no ci record for "
                f"provider {provider!r} workflow "
                f"{workflow!r}") from None

    def register_records(self, records: Any):
        """Hold a set of run records, validated whole.

        Every record is validated, and checked against
        the records already held and within the set,
        before anything is held, so a refusal holds
        nothing new.
        """
        validated = []
        seen: set = set()
        for record in records:
            held = _ci_coerce_record(record)
            held.validate(self._providers)
            key = (held.provider, held.workflow)
            if key in self._records or key in seen:
                raise ValueError(
                    "a ci record for provider "
                    f"{held.provider!r} workflow "
                    f"{held.workflow!r} already stands "
                    "held for the session")
            seen.add(key)
            validated.append(held)
        for held in validated:
            self._records[(held.provider, held.workflow)] = held
        return validated

    def list_records(self) -> list:
        """The run records held one by one, in hold order."""
        return list(self._records.values())

    def list_items(self) -> list:
        """Everything held: the run records and the drafts."""
        return (list(self._records.values())
                + list(self._drafts.values()))

    def standings(self) -> list:
        """The held records' standings, derived at call time."""
        from ..core.ci_bridges import derive_standing
        return [derive_standing(record, self._providers)
                for record in self._records.values()]

    def hold_draft(self, provider: Any, workflow: Any,
                   change: Any,
                   trigger: Any = "workflow_dispatch"):
        """Propose one workflow draft, held for the session.

        The draft is shaped by the pure layer alone -
        a trigger other than manual dispatch refuses
        by name there, and a draft is never applied.
        A second draft for a provider and workflow
        already drafted refuses likewise.
        """
        from ..core.ci_bridges import propose_draft
        draft = propose_draft(provider, workflow, change,
                              trigger=trigger,
                              registry=self._providers)
        key = (draft.provider, draft.workflow)
        if key in self._drafts:
            raise ValueError(
                "a workflow draft for provider "
                f"{draft.provider!r} workflow "
                f"{draft.workflow!r} already stands held "
                "for the session")
        self._drafts[key] = draft
        return draft

    def get_draft(self, provider: Any, workflow: Any):
        """The held draft for one provider and workflow."""
        from ..core.validation import ValidationError
        try:
            return self._drafts[(provider, workflow)]
        except KeyError:
            raise ValidationError(
                "the session holds no workflow draft for "
                f"provider {provider!r} workflow "
                f"{workflow!r}") from None

    def list_drafts(self) -> list:
        """The workflow drafts held, in proposal order."""
        return list(self._drafts.values())

    def book(self):
        """The held pieces composed as a CI bridges book.

        The book is plain data: the shipped provider
        registry's entries beside the run records and
        workflow drafts held for the session, under the
        pure layer's schema word.
        """
        from ..core.ci_bridges import CI_BRIDGE_SCHEMA
        return {
            "schema": CI_BRIDGE_SCHEMA,
            "providers": [_ci_provider_dict(entry)
                          for entry in self._providers.entries()],
            "records": [_ci_record_dict(record)
                        for record in self._records.values()],
            "drafts": [_ci_draft_dict(draft)
                       for draft in self._drafts.values()],
        }


def parse_cibridges_args(args: Any):
    """Parse /cibridges arguments (M-247).

    Returns ``(stance, target, (), None)``: the bare
    command and ``show`` stand as ``("show", None, (),
    None)``; ``providers``, ``index`` and ``verdict``
    name their own stance with no target; ``provider
    <provider>`` names one provider; ``record
    <provider> <workflow>``, ``standing <provider>
    <workflow>`` and ``draft <provider> <workflow>``
    name one provider and workflow as a pair; the bare
    ``draft`` stance names the session's drafts.
    Anything else raises ValueError carrying the usage
    line, exactly as the sibling parsers refuse.
    """
    text = (args or "").strip()
    if not text or text == "show":
        return ("show", None, (), None)
    parts = text.split()
    head, rest = parts[0], parts[1:]
    if head in ("providers", "index", "verdict"):
        if rest:
            raise ValueError(CIBRIDGES_USAGE)
        return (head, None, (), None)
    if head == "provider":
        if len(rest) != 1:
            raise ValueError(CIBRIDGES_USAGE)
        return (head, rest[0], (), None)
    if head in ("record", "standing"):
        if len(rest) != 2:
            raise ValueError(CIBRIDGES_USAGE)
        return (head, (rest[0], rest[1]), (), None)
    if head == "draft":
        if not rest:
            return ("drafts", None, (), None)
        if len(rest) != 2:
            raise ValueError(CIBRIDGES_USAGE)
        return ("draft", (rest[0], rest[1]), (), None)
    raise ValueError(CIBRIDGES_USAGE)


