class ExportEverythingRegistry:
    """Session registry for the export everything (M-251).

    The registry lives in the agent layer alone - it is
    session state, not a stored setting - and wraps the
    pure layer (``mythic_agent.core.export_everything``): it
    holds the shipped kind registry (one entry per
    kind, held as data) beside the export records held
    one by one for the session, one record per kind and
    record, and the bundle drafts prepared for the
    session, one draft draft per bundle. An record
    is validated whole by the pure layer before it is
    held - an record naming an unknown kind, scope or
    evidence kind refuses by name here too, and a refusal
    holds nothing new. A second record for a kind and
    record already held refuses likewise. Drafts are
    prepared only through the pure layer's draft road
    - state ready by default, may be marked shared
    by a human, and never exported or built: the doors
    prepare bundles and export nothing here. Holding
    performs no export, calls no host API, probes
    no network and starts nothing: the registry holds
    tellings as data, alone.
    """

    def __init__(self) -> None:
        from ..core.export_everything import default_registry
        self._kinds = default_registry()
        self._records: dict[tuple, Any] = {}
        self._drafts: dict[str, Any] = {}

    def kinds(self):
        """The shipped kind registry held by the session."""
        return self._kinds

    def register_record(self, record: Any):
        """Hold one export record, validated whole.

        A second record for a kind and record already
        held refuses, and a refusal holds nothing new.
        """
        held = _ee_coerce_record(record)
        held.validate(self._kinds)
        key = (held.kind, held.record)
        if key in self._records:
            raise ValueError(
                "an export record for kind "
                f"{held.kind!r} record "
                f"{held.record!r} already stands held "
                "for the session")
        self._records[key] = held
        return held

    def get_record(self, kind: Any, record: Any):
        """The held record for one kind and record."""
        from ..core.validation import ValidationError
        try:
            return self._records[(kind, record)]
        except KeyError:
            raise ValidationError(
                "the session holds no export record "
                f"for kind {kind!r} record "
                f"{record!r}") from None

    def register_records(self, records: Any):
        """Hold a set of export records, validated whole.

        Every record is validated, and checked against
        the records already held and within the set,
        before anything is held, so a refusal holds
        nothing new.
        """
        validated = []
        seen: set = set()
        for record in records:
            held = _ee_coerce_record(record)
            held.validate(self._kinds)
            key = (held.kind, held.record)
            if key in self._records or key in seen:
                raise ValueError(
                    "an export record for kind "
                    f"{held.kind!r} record "
                    f"{held.record!r} already stands "
                    "held for the session")
            seen.add(key)
            validated.append(held)
        for held in validated:
            self._records[(held.kind, held.record)] = held
        return validated

    def list_records(self) -> list:
        """The export records held one by one, in hold order."""
        return list(self._records.values())

    def list_items(self) -> list:
        """Everything held: the records and the drafts."""
        return (list(self._records.values())
                + list(self._drafts.values()))

    def standings(self) -> list:
        """The held records' standings, derived at call time."""
        from ..core.export_everything import derive_standing
        return [derive_standing(record, self._kinds)
                for record in self._records.values()]

    def hold_draft(self, bundle: Any, kind: Any,
                      record: Any, draft: Any,
                      state: Any = "ready"):
        """Prepare one bundle draft draft, held for the session.

        The draft is shaped by the pure layer alone -
        an state word outside ready/shared refuses
        by name there, and a draft is never exported or
        built. A second draft draft for a bundle
        already prepared refuses likewise.
        """
        from ..core.export_everything import prepare_draft
        draft = prepare_draft(bundle, kind, record,
                                 draft, state=state)
        if draft.bundle in self._drafts:
            raise ValueError(
                "a bundle draft draft for bundle "
                f"{draft.bundle!r} already stands held "
                "for the session")
        self._drafts[draft.bundle] = draft
        return draft

    def get_draft(self, bundle: Any):
        """The held draft draft for one bundle."""
        from ..core.validation import ValidationError
        try:
            return self._drafts[bundle]
        except KeyError:
            raise ValidationError(
                "the session holds no bundle draft for "
                f"bundle {bundle!r}") from None

    def list_drafts(self) -> list:
        """The bundle draft drafts held, in draft order."""
        return list(self._drafts.values())

    def book(self):
        """The held pieces composed as a export everything book.

        The book is plain data: the shipped kind
        registry's entries beside the export records and
        bundle drafts held for the session, under the
        pure layer's schema word.
        """
        from ..core.export_everything import EXPORT_EVERYTHING_SCHEMA
        return {
            "schema": EXPORT_EVERYTHING_SCHEMA,
            "kinds": [_ee_kind_dict(entry)
                        for entry in self._kinds.entries()],
            "records": [_ee_record_dict(record)
                        for record in self._records.values()],
            "drafts": [_ee_draft_dict(draft)
                       for draft in self._drafts.values()],
        }


def parse_exporteverything_args(args: Any):
    """Parse /exporteverything arguments (M-251).

    Returns ``(stance, target, (), None)``: the bare
    command and ``show`` stand as ``("show", None, (),
    None)``; ``kinds``, ``index`` and ``verdict`` name
    their own stance with no target; ``kind <kind>``
    names one kind; ``record <kind> <record>`` and
    ``standing <kind> <record>`` name one kind and record
    as a pair; ``prepare <bundle>`` names one bundle
    and the bare ``prepare`` stance names the session's
    draft drafts. Anything else raises ValueError
    carrying the usage line, exactly as the sibling
    parsers refuse.
    """
    text = (args or "").strip()
    if not text or text == "show":
        return ("show", None, (), None)
    parts = text.split()
    head, rest = parts[0], parts[1:]
    if head in ("kinds", "index", "verdict"):
        if rest:
            raise ValueError(EXPORTEVERYTHING_USAGE)
        return (head, None, (), None)
    if head == "kind":
        if len(rest) != 1:
            raise ValueError(EXPORTEVERYTHING_USAGE)
        return (head, rest[0], (), None)
    if head in ("record", "standing"):
        if len(rest) != 2:
            raise ValueError(EXPORTEVERYTHING_USAGE)
        return (head, (rest[0], rest[1]), (), None)
    if head == "prepare":
        if not rest:
            return ("drafts", None, (), None)
        if len(rest) != 1:
            raise ValueError(EXPORTEVERYTHING_USAGE)
        return ("prepare", rest[0], (), None)
    raise ValueError(EXPORTEVERYTHING_USAGE)


