    def mimis_roads_green(self):
        """The session book's slices standing ready (M-218)."""
        from ..core.mimisbrunnr_road import (
            green_roads as _green)
        return _green(self.mimis_book())

    def mimis_panel(self, view: Any = None):
        """The panel derived for the whole book (M-218).

        Derived under the named view, or under the
        book's default view when none is named; a book
        holding no view at all refuses plainly rather
        than inventing one.
        """
        from ..core.mimisbrunnr_road import (
            derive_panel as _derive_panel)
        book = self.mimis_book()
        resolved = view if view is not None \
            else self._mimis_default_view(book)
        if resolved is None:
            raise ValueError(
                "no view stands in the book to derive a panel under")
        return _derive_panel(book, resolved)

    def mimis_verdict(self, view: Any = None):
        """The verdict derived for the whole book (M-218).

        Derived under the named view, or under the
        book's default view when none is named; a book
        holding no view at all refuses plainly rather
        than inventing one.
        """
        from ..core.mimisbrunnr_road import (
            derive_verdict as _derive_verdict)
        book = self.mimis_book()
        resolved = view if view is not None \
            else self._mimis_default_view(book)
        if resolved is None:
            raise ValueError(
                "no view stands in the book to derive a verdict under")
        return _derive_verdict(book, resolved)

