    def idecompanions_panel(self, view: Any = None):
        """The panel derived for the whole book (M-240).

        Derived under the declared view, or under the
        book's default view when none is declared; a book
        holding no view at all refuses plainly rather
        than inventing one.
        """
        from ..core.ide_companions import (
            derive_panel as _derive_panel)
        book = self.idecompanions_book()
        resolved = view if view is not None \
            else self._idecompanions_default_view(book)
        if resolved is None:
            raise ValueError(
                "no view stands in the book to derive a panel under")
        return _derive_panel(book, resolved)

