    def rivalimporters_panel(self, view: Any = None):
        """The panel derived for the whole book (M-241).

        Derived under the detected view, or under the
        book's default view when none is detected; a book
        holding no view at all refuses plainly rather
        than inventing one.
        """
        from ..core.rival_importers import (
            derive_panel as _derive_panel)
        book = self.rivalimporters_book()
        resolved = view if view is not None \
            else self._rivalimporters_default_view(book)
